// ===================================================================
// CÓDIGO BICICORUÑA CON TIPOS DE VEHÍCULOS
// ===================================================================

const items = $input.all();

let stationInfoArray = null;
let stationStatusArray = null;

// Procesar cada item que llega
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const data = item.json;

  let stations = null;

  if (data.stations) {
    stations = data.stations;
  } else if (data.data && data.data.stations) {
    stations = data.data.stations;
  }

  if (stations && stations.length > 0) {
    const firstStation = stations[0];

    if (firstStation.name !== undefined && firstStation.address !== undefined) {
      stationInfoArray = stations;
    } else if (firstStation.num_bikes_available !== undefined) {
      stationStatusArray = stations;
    }
  }
}

// Validar que tenemos ambos arrays
if (!stationInfoArray || !stationStatusArray) {
  throw new Error('ERROR: No se encontraron ambos arrays de datos');
}

// Ahora combinar los datos
const result = [];

for (let i = 0; i < stationInfoArray.length; i++) {
  const info = stationInfoArray[i];

  const status = stationStatusArray.find(s => s.station_id === info.station_id);

  // Extraer valores básicos
  const totalBikes = status ? Number(status.num_bikes_available) : 0;
  const docks = status ? Number(status.num_docks_available) : 0;
  const cap = Number(info.capacity) || 0;

  // ============================================
  // EXTRAER BICIS ELÉCTRICAS DEL ARRAY vehicle_types_available
  // ============================================
  let electricBikes = 0;
  let normalBikes = 0;

  if (status && status.vehicle_types_available && Array.isArray(status.vehicle_types_available)) {
    for (let j = 0; j < status.vehicle_types_available.length; j++) {
      const vehicleType = status.vehicle_types_available[j];
      const typeId = vehicleType.vehicle_type_id;
      const count = Number(vehicleType.count) || 0;

      // EFIT y BOOST son eléctricas
      if (typeId === 'EFIT' || typeId === 'BOOST') {
        electricBikes += count;
      }
      // FIT son normales
      else if (typeId === 'FIT') {
        normalBikes += count;
      }
    }
  } else {
    // Fallback: si no hay vehicle_types_available, asumimos todas normales
    normalBikes = totalBikes;
  }

  // Calcular ocupación
  const occ = cap > 0 ? Math.round((totalBikes / cap) * 100 * 100) / 100 : 0;

  // Estado
  let estado = 'available';
  if (totalBikes === 0) estado = 'empty';
  else if (docks === 0) estado = 'full';
  else if (totalBikes <= 2) estado = 'low_bikes';

  // Crear objeto de estación
  result.push({
    station_id: String(info.station_id),
    name: info.name,
    address: info.address || '',
    lat: Number(info.lat),
    lon: Number(info.lon),
    capacity: cap,
    num_bikes_available: totalBikes,
    num_docks_available: docks,
    num_ebikes_available: electricBikes,
    num_normal_bikes: normalBikes,
    occupancy_rate: occ,
    availability_status: estado,
    is_renting: status ? Boolean(status.is_renting) : true,
    is_returning: status ? Boolean(status.is_returning) : true,
    is_installed: status ? Boolean(status.is_installed) : true,
    last_reported: status ? status.last_reported : Math.floor(Date.now() / 1000),

    // Información adicional de tipos de vehículos
    vehicle_types: status && status.vehicle_types_available ? status.vehicle_types_available : []
  });
}

// Calcular totales
let totalBikes = 0;
let totalDocks = 0;
let totalCap = 0;
let totalElectric = 0;
let totalNormal = 0;

for (let i = 0; i < result.length; i++) {
  totalBikes += result[i].num_bikes_available;
  totalDocks += result[i].num_docks_available;
  totalCap += result[i].capacity;
  totalElectric += result[i].num_ebikes_available;
  totalNormal += result[i].num_normal_bikes;
}

// Crear respuesta final
const response = {
  success: true,
  timestamp: new Date().toISOString(),
  system: 'BiciCoruña',
  city: 'A Coruña',
  operator: 'EMVSA',
  summary: {
    total_stations: result.length,
    total_bikes: totalBikes,
    total_docks: totalDocks,
    total_capacity: totalCap,
    total_electric_bikes: totalElectric,
    total_normal_bikes: totalNormal,
    avg_occupancy: totalCap > 0 ? Math.round((totalBikes / totalCap) * 100 * 100) / 100 : 0
  },
  stations: result
};

return [{ json: response }];

const now = new Date();
const hour = now.getHours();
const dayOfWeek = now.getDay();
const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

function getOccupancy(parkingId, hour, isWeekend) {
  let base = 0.5;
  if (hour >= 8 && hour < 10) {
    base = parkingId === 'cantones' ? 0.90 : 0.65;
  } else if (hour >= 10 && hour < 14) {
    base = 0.75;
  } else if (hour >= 16 && hour < 20) {
    base = 0.70;
  } else if (hour >= 20 && hour < 23) {
    base = isWeekend ? 0.60 : 0.40;
  } else {
    base = 0.20;
  }
  const variation = (Math.random() - 0.5) * 0.15;
  return Math.max(0.1, Math.min(0.95, base + variation));
}

const parkingsList = [
  { id: 'cantones', name: 'Parking Cantones', address: 'Cantones, 15001', lat: 43.3713, lon: -8.3960, capacity: 400, price: 2.07, distance: 0.3, walk: 4 },
  { id: 'palexco', name: 'Parking Palexco', address: 'Av. Arteixo, 15007', lat: 43.3673, lon: -8.4047, capacity: 450, price: 1.85, distance: 1.2, walk: 15 },
  { id: 'papagayo', name: 'Parking Papagayo', address: 'Av. Papagayo, 15190', lat: 43.3556, lon: -8.4201, capacity: 500, price: 1.60, distance: 2.5, walk: 30 },
  { id: 'casa_agua', name: 'Parking Casa del Agua', address: 'Paseo Marítimo, 15002', lat: 43.3645, lon: -8.4028, capacity: 350, price: 1.95, distance: 0.8, walk: 10 },
  { id: 'opera', name: 'Parking Palacio Ópera', address: 'Glorieta América, 15004', lat: 43.3701, lon: -8.3989, capacity: 280, price: 2.15, distance: 0.5, walk: 6 },
  { id: 'parrote', name: 'Parking O Parrote', address: 'C/ Parrote, 15001', lat: 43.3689, lon: -8.3945, capacity: 320, price: 2.00, distance: 0.4, walk: 5 },
  { id: 'maria_pita', name: 'Parking María Pita', address: 'Plaza María Pita, 15001', lat: 43.3715, lon: -8.3975, capacity: 180, price: 2.30, distance: 0.2, walk: 3 }
];

const result = parkingsList.map(p => {
  const occRate = getOccupancy(p.id, hour, isWeekend);
  const occupied = Math.round(p.capacity * occRate);
  const free = p.capacity - occupied;

  let status = 'available';
  if (free === 0) status = 'full';
  else if (free < 10) status = 'almost_full';
  else if (free < 30) status = 'limited';

  let risk = 'low';
  if (free < 5) risk = 'high';
  else if (free < 20) risk = 'medium';

  return {
    id: p.id,
    name: p.name,
    address: p.address,
    location: {              // ← ESTRUCTURA CORRECTA
      lat: p.lat,
      lon: p.lon
    },
    capacity: p.capacity,
    price_per_hour: p.price,
    distance_to_center: p.distance,
    walking_time: p.walk,
    current_status: {        // ← ESTRUCTURA CORRECTA
      free_spots: free,
      occupied_spots: occupied,
      occupancy_rate: Math.round(occRate * 100),
      status: status,
      risk: risk,
      last_updated: now.toISOString()
    }
  };
});

return [{ 
  json: {
    success: true,
    timestamp: now.toISOString(),
    parkings: result
  }
}];
